#include<stdio.h> #include<string.h> #define MAX 20 #define true 1 #define false 0 int top = -1; int stack[MAX]; /*Begin of push*/ char push(char item) { if(top == (MAX-1)) printf("Stack Overflow
"); else { top=top+1; stack[top] = item; } } /*Begin of pop*/ char pop() { if(top == -1) printf("Stack Underflow
"); else return(stack[top--]); } main() { char exp[MAX],temp; int i,valid=true; printf("Enter an algebraic expression : "); gets(exp); for(i=0;i<strlen(exp);i++) { if(exp[i]=='(' || exp[i]=='{' || exp[i]=='[') { push( exp[i] ); printf("%c",exp[i]); } if(exp[i]==')' || exp[i]=='}' || exp[i]==']') { if(top == -1) /* stack empty */ valid=false; else { temp=pop(); if( exp[i]==')' && (temp=='{' || temp=='[') ) valid=false; if( exp[i]=='}' && (temp=='(' || temp=='[') ) valid=false; if( exp[i]==']' && (temp=='(' || temp=='{') ) valid=false; } } } if(top>=0) /*stack not empty*/ valid=false; if( valid==true ) printf("Valid expression
"); else printf("Invalid expression
"); }
